use objc2::rc::autoreleasepool;
use objc2_app_kit::NSPasteboard;

/// 클립보드가 바뀔 때마다 증가하는 카운터. 복사가 일어났는지 판별하는 데 쓴다.
/// 폴링 스레드에서 계속 불리므로, autorelease 된 객체가 쌓이지 않게 풀로 감싼다.
pub fn clipboard_change_count() -> isize {
    autoreleasepool(|_| NSPasteboard::generalPasteboard().changeCount())
}

/// 클립보드를 감시하는 앱이 건드리지 말아야 할 내용에 붙는 표식 (http://nspasteboard.org).
/// 비밀번호 관리자 등이 복사한 내용에 붙인다.
const SENSITIVE_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

/// 지금 클립보드 내용이 외부로 보내면 안 되는 것으로 표시돼 있는지 확인한다.
pub fn clipboard_is_sensitive() -> bool {
    autoreleasepool(|_| {
        NSPasteboard::generalPasteboard().types().is_some_and(|types| {
            types
                .iter()
                .any(|ty| SENSITIVE_TYPES.contains(&ty.to_string().as_str()))
        })
    })
}
